describe('assertSafeShellArg', () => {
  it('accepts safe arguments', () => {
    expect(assertSafeShellArg('hello')).toBe('hello');
    expect(assertSafeShellArg('/path/to/file')).toBe('/path/to/file');
    expect(assertSafeShellArg('key=value')).toBe('key=value');
  });

  it('rejects unsafe arguments', () => {
    expect(() => assertSafeShellArg('')).toThrow();
    expect(() => assertSafeShellArg('$(cmd)')).toThrow();
    expect(() => assertSafeShellArg('a b')).toThrow();
  });
});

describe('assertSafeCommandName', () => {
  it('accepts valid command names', () => {
    expect(assertSafeCommandName('git')).toBe('git');
    expect(assertSafeCommandName('node_modules')).toBe('node_modules');
  });

  it('rejects path separators and spaces', () => {
    expect(() => assertSafeCommandName('/usr/bin/git')).toThrow();
    expect(() => assertSafeCommandName('cmd arg')).toThrow();
  });
});

describe('sanitizeSessionId', () => {
  it('passes through safe IDs', () => {
    expect(sanitizeSessionId('abc-123.test')).toBe('abc-123.test');
  });

  it('replaces unsafe characters with underscore', () => {
    expect(sanitizeSessionId('id with spaces')).toBe('id_with_spaces');
    expect(sanitizeSessionId('id/path')).toBe('id_path');
  });

  it('returns empty for empty input', () => {
    expect(sanitizeSessionId('')).toBe('');
  });
});
